import{_ as t,o as i,c as r,ag as e}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"配置工业采集连接","description":"创建工业协议连接、准备变量，选择兼容节点验证，并分清配置、调试和正式部署。","frontmatter":{"title":"配置工业采集连接","description":"创建工业协议连接、准备变量，选择兼容节点验证，并分清配置、调试和正式部署。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/industrial-connections.md","filePath":"zh/使用指南/配置工业采集连接.md"}'),o={name:"zh/guide/industrial-connections.md"};function l(n,a,s,d,h,p){return i(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="配置工业采集连接" tabindex="-1">配置工业采集连接 <a class="header-anchor" href="#配置工业采集连接" aria-label="Permalink to &quot;配置工业采集连接&quot;">​</a></h1><p>本页用于在工程中准备工业协议连接和变量，并通过已准备好的兼容节点检查连接。<strong>保存配置、调试连接和正式部署是不同步骤。</strong></p><p>操作前，先取得工程权限与设备负责人的授权，准备：</p><ul><li>设备型号、使用的协议及连接参数。</li><li>有需要时准备 IP、端口、串口或设备认证资料；只填写所选类型实际要求的字段。</li><li>变量地址、数据类型及必要的读取约定。</li><li>要调试时，准备可访问该设备、已登记且能力匹配的在线采集节点与运行环境。</li></ul><p>没有在线节点，也可以先保存连接和变量配置；不能因此宣称已经读到设备数据。协议、驱动和节点要求以交付包及页面能力提示为准，不代表所有设备型号都可直接接入。</p><h2 id="_1-创建工业连接" tabindex="-1">1. 创建工业连接 <a class="header-anchor" href="#_1-创建工业连接" aria-label="Permalink to &quot;1. 创建工业连接&quot;">​</a></h2><ol><li>从“工程管理”打开目标工程的 <strong>“数据中心”</strong>。</li><li>选择 <strong>“工业采集”</strong>，点击 <strong>“新建工业连接”</strong>。</li><li>从左侧搜索并选择正确的采集类型。</li><li>核对协议、驱动版本与能力提示，填写连接名称及右侧要求的参数。</li><li>点击 <strong>“创建连接”</strong>，等待成功，再在连接列表找到它。</li></ol><p>不清楚设备参数时先向负责人确认，不直接照抄其他设备的地址或凭据。类型暂不可用时使用“重新加载”，不要选择另一个协议凑合保存。</p><p>连接多时，可搜索名称或协议，并向下滚动继续加载。列表显示的是已加载数量，不一定是工程的全部连接。</p><h2 id="_2-核对连接配置" tabindex="-1">2. 核对连接配置 <a class="header-anchor" href="#_2-核对连接配置" aria-label="Permalink to &quot;2. 核对连接配置&quot;">​</a></h2><p>选择连接，进入 <strong>“连接配置”</strong>。修改名称、连接参数或默认采集参数后，点击 <strong>“保存配置”</strong>，等到“连接配置已保存”，再重新打开核对。</p><p>“启用连接”、采集周期、数值死区和“仅变化时上报”等选项按业务需要安排；不知道设备负载和业务要求时，不把采集周期直接设到很小。</p><p>这一步保存的是配置，不要求节点在线，也不等于连接测试已经成功。</p><h2 id="_3-添加一个变量" tabindex="-1">3. 添加一个变量 <a class="header-anchor" href="#_3-添加一个变量" aria-label="Permalink to &quot;3. 添加一个变量&quot;">​</a></h2><ol><li>进入 <strong>“变量建模”</strong>，选择合适分组，点击 <strong>“新建变量”</strong>。</li><li>填写变量名称，按设备资料选择数据类型和地址；元素数量等字段只在对应类型需要时填写。</li><li>没有独立要求时使用 **“继承连接默认”**采集参数；需要不同参数时再选择“单独覆盖”。</li><li>查看地址校验提示和“将保存为”结果，确认与设备约定一致。</li><li>点击 <strong>“保存变量”</strong>，核对列表及保存后的变量详情。</li></ol><p>地址格式和类型限制随协议变化，不在这里套用通用寄存器或位地址。字段被锁定时先看提示，不通过删除再建规避保护。</p><p>保存后可到<a href="/induframe-docs/zh/guide/datapoints.html">数据点列表</a>核对生成的点及来源；存在数据点不代表已经获得实时读数。</p><h2 id="_4-选择节点并验证" tabindex="-1">4. 选择节点并验证 <a class="header-anchor" href="#_4-选择节点并验证" aria-label="Permalink to &quot;4. 选择节点并验证&quot;">​</a></h2><p>只有在获准读取设备、节点和网络都已准备好时才执行：</p><ol><li>进入 <strong>“部署与验证”</strong>，核对“运行环境”。</li><li>在“调试与部署”选择兼容的在线节点；需要保存部署位置时，点击该区域的 <strong>“保存”</strong>。</li><li>等待“调试器已就绪”，再点击 <strong>“连接”</strong>。</li><li>查看是否变为“已连接”；失败时先保留旁边的具体错误。</li><li>协议支持点位读取时，可在“变量建模”使用 <strong>“获取当前页数据”</strong>，核对本次读取结果、时间和失败信息。</li></ol><p>“已连接”不等于每个变量地址都正确。“获取当前页数据”只读取当前页，不代表全部变量都已检查。协议不提供该操作时，不会因为换一个节点就自动增加能力。</p><p>节点离线、能力不匹配或没有兼容节点时，先请维护人员处理。不要把平台中心已经安装好当成采集节点已准备好；中心目前优先推荐已测试的 Ubuntu 24，具体驱动与节点的平台要求仍需分别确认。</p><h2 id="_5-结束调试与后续部署" tabindex="-1">5. 结束调试与后续部署 <a class="header-anchor" href="#_5-结束调试与后续部署" aria-label="Permalink to &quot;5. 结束调试与后续部署&quot;">​</a></h2><p>结束本次调试时，回到“部署与验证”使用 <strong>“断开”</strong>；连接列表更多操作也提供“断开连接”。核对状态结束，不用删除连接代替断开。</p><p>保存节点位置和调试成功都不等于工程已正式部署。正式运行仍需按工程版本、运行环境和部署安排检查实际数据。页面提示“工程已部署，撤销部署后才能改”时，应先与运维人员确认，不直接撤销正在使用的部署。</p><h2 id="_6-删除前先检查影响" tabindex="-1">6. 删除前先检查影响 <a class="header-anchor" href="#_6-删除前先检查影响" aria-label="Permalink to &quot;6. 删除前先检查影响&quot;">​</a></h2><p>连接列表更多操作中的 **“删除连接”**会先检查依赖，并在确认框说明影响。存在调试长连接时先断开；还有其他使用关系时先处理提示的依赖。</p><p>删除会移除连接及其来源内配置，已生成的数据点会保留并标记为无效。只有确认无需保留、理解影响后才点击“删除”；操作结果不明确时先刷新，不连续重复提交。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="/induframe-docs/zh/guide/datapoints.html">查看和整理数据点</a> · <a href="/induframe-docs/zh/guide/datacenter.html">返回数据中心入门</a> · <a href="/induframe-docs/zh/concepts/development-and-runtime.html">理解开发、发布与运行</a>。</p>',30)])])}const u=t(o,[["render",l]]);export{_ as __pageData,u as default};
